const button=document.querySelector('#validate'),input=document.querySelector('#record-json'),output=document.querySelector('#validation-output'),fields=JSON.parse(document.querySelector('#contract-data').textContent),copy=JSON.parse(document.querySelector('#copy-data').textContent);function validate(){let value;try{value=JSON.parse(input.value)}catch{output.className='result invalid';output.textContent=copy.invalid;return}const missing=fields.filter(field=>field.required&&(value[field.name]===undefined||value[field.name]===null||value[field.name]==='')).map(field=>field.name);output.className='result '+(missing.length?'invalid':'valid');output.textContent=missing.length?copy.invalid+' '+missing.join(', '):copy.valid}button.addEventListener('click',validate);validate();
